
export default {
  props: {
    data: {
      type: Object,
      required: true,
    },
    i18n: {
      type: Object,
      required: true,
    },
    autoFocus: {
      type: Boolean,
      default: false,
    },
    onSearch: {
      type: Function,
      required: true,
    },
    onArrowLeft: {
      type: Function,
      required: false,
    },
    onArrowRight: {
      type: Function,
      required: false,
    },
    onArrowDown: {
      type: Function,
      required: false,
    },
    onArrowUp: {
      type: Function,
      required: false,
    },
    onEnter: {
      type: Function,
      required: false,
    },
  },
  emits: ['search', 'enter', 'arrowUp', 'arrowDown', 'arrowRight', 'arrowLeft'],
  data() {
    return {
      value: '',
    }
  },
  computed: {
    emojiIndex() {
      return this.data
    },
  },
  watch: {
    value() {
      this.$emit('search', this.value)
    },
  },
  methods: {
    clear() {
      this.value = ''
    },
  },
  mounted() {
    let $input = this.$el.querySelector('input')

    if (this.autoFocus) {
      $input.focus()
    }
  },
}
