

export default {
  props: {
    skin: {
      type: Number,
      required: true
    }
  },
  emits: ['change'],
  data() {
    return {
      opened: false
    }
  },
  methods: {
    onClick(skinTone) {
      if (this.opened) {
        if (skinTone != this.skin) {
          this.$emit('change', skinTone)
        }
      }

      this.opened = !this.opened
    }
  }
}

